CREATE TABLE user_scope_settings (user_id TEXT PRIMARY KEY REFERENCES users(id), scopes TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE session_security (token_hash TEXT PRIMARY KEY REFERENCES sessions(token_hash) ON DELETE CASCADE, reauthenticated_at TEXT, mfa_at TEXT);
CREATE TABLE user_mfa (user_id TEXT PRIMARY KEY REFERENCES users(id), encrypted_secret TEXT NOT NULL, confirmed INTEGER NOT NULL DEFAULT 0, last_counter INTEGER NOT NULL DEFAULT -1, enrolled_at TEXT NOT NULL);
CREATE TABLE task_details (task_id TEXT PRIMARY KEY REFERENCES tasks(id) ON DELETE CASCADE, version INTEGER NOT NULL DEFAULT 1, teacher_notes TEXT NOT NULL DEFAULT '', answer_key TEXT NOT NULL DEFAULT '', reading_metadata TEXT NOT NULL DEFAULT '[]', updated_at TEXT NOT NULL);
CREATE TABLE submission_details (submission_id TEXT PRIMARY KEY REFERENCES submissions(id) ON DELETE CASCADE, task_version INTEGER NOT NULL, created_at TEXT NOT NULL, feedback_version INTEGER NOT NULL DEFAULT 0, feedback_submission_version INTEGER, feedback_at TEXT);
CREATE TABLE submission_history (submission_id TEXT NOT NULL REFERENCES submissions(id) ON DELETE CASCADE, version INTEGER NOT NULL, task_version INTEGER NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(submission_id,version));
CREATE TABLE feedback_history (id TEXT PRIMARY KEY, submission_id TEXT NOT NULL REFERENCES submissions(id) ON DELETE CASCADE, submission_version INTEGER NOT NULL, feedback_version INTEGER NOT NULL, feedback TEXT NOT NULL, author_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, UNIQUE(submission_id,feedback_version));
CREATE TABLE work_items (kind TEXT NOT NULL, resource_id TEXT NOT NULL, version INTEGER NOT NULL, assignee_id TEXT REFERENCES users(id), priority TEXT NOT NULL CHECK(priority IN ('low','normal','high','urgent')), due_at TEXT, next_action TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(kind,resource_id));
CREATE TABLE publication_stages (id TEXT PRIMARY KEY, record_id TEXT NOT NULL, revision INTEGER NOT NULL, content_hash TEXT NOT NULL, stage TEXT NOT NULL CHECK(stage IN ('export','build','deploy','feed')), commit_sha TEXT, artifact_hash TEXT NOT NULL, url TEXT, observed_at TEXT NOT NULL, evidence_source TEXT NOT NULL, UNIQUE(record_id,revision,stage,artifact_hash));
CREATE INDEX publication_stage_record ON publication_stages(record_id,revision,stage);
CREATE TABLE correction_closures (correction_id TEXT PRIMARY KEY REFERENCES corrections(id), revision INTEGER NOT NULL, publication_id TEXT NOT NULL REFERENCES publication_stages(id), evidence TEXT NOT NULL, closed_by TEXT NOT NULL REFERENCES users(id), closed_at TEXT NOT NULL);
CREATE TABLE rights_details (rights_id TEXT PRIMARY KEY REFERENCES rights(id), permissions TEXT NOT NULL, territory TEXT NOT NULL, starts_at TEXT, attribution TEXT NOT NULL, document_id TEXT REFERENCES attachments(id));
CREATE TABLE attachment_scans (attachment_id TEXT PRIMARY KEY REFERENCES attachments(id), status TEXT NOT NULL CHECK(status IN ('unknown','pending','clean','rejected')), scanner TEXT, evidence_hash TEXT, scanned_at TEXT);
CREATE TABLE order_fulfillments (order_id TEXT PRIMARY KEY REFERENCES orders(id), version INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('planned','in-progress','delivered','confirmed','cancelled')), delivery_note TEXT NOT NULL, delivery_url TEXT, updated_by TEXT REFERENCES users(id), updated_at TEXT NOT NULL, confirmed_at TEXT);
CREATE TABLE notification_deliveries (job_id TEXT PRIMARY KEY REFERENCES jobs(id), status TEXT NOT NULL CHECK(status IN ('accepted','delivered','failed','expired')), provider_event_id TEXT UNIQUE, accepted_at TEXT NOT NULL, updated_at TEXT NOT NULL, expires_at TEXT NOT NULL, receipt_hash TEXT);
CREATE TABLE metric_windows (window TEXT PRIMARY KEY, requests INTEGER NOT NULL, server_errors INTEGER NOT NULL, duration_histogram TEXT NOT NULL);
CREATE TABLE recovery_events (sequence INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL CHECK(kind IN ('withhold','delete-account','role','scopes','offboard')), target_id TEXT NOT NULL, payload TEXT NOT NULL, occurred_at TEXT NOT NULL);
